use std::io;

fn read_num() -> Result<i32, io::Error> {
    let s = "42";
    let n: i32 = s.parse()?;
    Ok(n)
}

use std::num::ParseIntError;

enum MyErr { Parse(ParseIntError) }

impl From<ParseIntError> for MyErr {
    fn from(e: ParseIntError) -> Self {
        MyErr::Parse(e)
    }
}
